class Node:
    def __init__(self):
        self.children = {}
        self.passing = 0
        self.ending = 0


class Trie:
    def __init__(self):
        self.root = Node()

    def insert(self, word):
        node = self.root
        for char in word:
            node = node.children.setdefault(char, Node())
            node.passing += 1
        node.ending += 1

    def _walk(self, text):
        node = self.root
        for char in text:
            node = node.children.get(char)
            if node is None:
                return None
        return node

    def countWordsEqualTo(self, word):
        node = self._walk(word)
        return node.ending if node else 0

    def countWordsStartingWith(self, prefix):
        node = self._walk(prefix)
        return node.passing if node else 0

    def erase(self, word):
        node = self.root
        for char in word:
            node = node.children[char]
            node.passing -= 1
        node.ending -= 1

