def complete_string(words):
    root = {}
    for word in words:
        node = root
        for char in word:
            node = node.setdefault(char, {})
        node["$"] = True

    def complete(word):
        node = root
        for char in word:
            node = node[char]
            if "$" not in node:
                return False
        return True

    best = ""
    for word in words:
        longer = len(word) > len(best) or (len(word) == len(best) and word < best)
        if longer and complete(word):
            best = word
    return best

