def find_maximum_xor(nums):
    root = {}
    for value in nums:
        node = root
        for bit in range(30, -1, -1):
            node = node.setdefault((value >> bit) & 1, {})
    best = 0
    for value in nums:
        node = root
        current = 0
        for bit in range(30, -1, -1):
            want = 1 - ((value >> bit) & 1)
            if want in node:
                current |= 1 << bit
                node = node[want]
            else:
                node = node[1 - want]
        best = max(best, current)
    return best

